package pe.ganadoconecta.modulos.reproduccion.adaptadores.entrada.http;import java.time.*;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.ganadoconecta.modulos.identidad.adaptadores.entrada.http.IdentidadAutenticada;import pe.ganadoconecta.modulos.reproduccion.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
@RestController @Profile("postgres") @RequestMapping("/api/v1/ganaderias/{ganaderiaId}/animales/{madreId}/partos") public class PartosControlador{private final RegistrarParto registrar;private final ListarPartos listar;public PartosControlador(RegistrarParto r,ListarPartos l){registrar=r;listar=l;}@PostMapping ResponseEntity<Resultado> registrar(@PathVariable UUID ganaderiaId,@PathVariable UUID madreId,@RequestBody Solicitud b,@AuthenticationPrincipal IdentidadAutenticada i){var x=registrar.ejecutar(b.dominio(ganaderiaId,madreId),i.usuarioId(),i.sesionId());return ResponseEntity.status(x.estado()==ResultadoRegistroParto.Estado.APLICADO?201:200).cacheControl(CacheControl.noStore()).body(new Resultado(x.operationId(),x.partoId(),x.estado().name(),x.confirmadoEn()));}@GetMapping ResponseEntity<List<Respuesta>> listar(@PathVariable UUID ganaderiaId,@PathVariable UUID madreId,@AuthenticationPrincipal IdentidadAutenticada i){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(listar.ejecutar(i.usuarioId(),ganaderiaId,madreId).stream().map(Respuesta::de).toList());}
 record Solicitud(UUID operationId,UUID partoId,Integer schemaVersion,LocalDate fecha,String resultado,UUID padreId,String observaciones,List<UUID> criaIds){SolicitudParto dominio(UUID g,UUID m){try{return new SolicitudParto(g,m,partoId,operationId,schemaVersion==null?0:schemaVersion,fecha,ResultadoParto.valueOf(resultado),padreId,observaciones,criaIds);}catch(Exception x){throw new DatoReproductivoInvalidoException("resultado");}}}record Resultado(UUID operationId,UUID partoId,String resultado,Instant confirmadoEn){}record Respuesta(UUID partoId,LocalDate fecha,String resultado,UUID padreId,String observaciones,List<UUID> criaIds,Instant creadoEn){static Respuesta de(Parto p){return new Respuesta(p.id(),p.fecha(),p.resultado().name(),p.padreId(),p.observaciones(),p.criaIds(),p.creadoEn());}}}
